let S,loadWarning='';try{const saved=localStorage.getItem('ascend-v1');const parsed=saved?JSON.parse(saved):{};if(!parsed||typeof parsed!=='object'||Array.isArray(parsed))throw new Error('Stored state is not an object');S={...defaultState(),...parsed}}catch{const damaged=(()=>{try{return localStorage.getItem('ascend-v1')}catch{return null}})();if(damaged){try{localStorage.setItem('ascend-corrupt-recovery',damaged)}catch{}}S=defaultState();loadWarning='Saved data could not be read. A raw recovery copy was preserved when browser storage allowed it; export or inspect it before clearing browser data.'};S.personal=S.personal||{days:{},examMode:false,milestones:[{id:'m1',name:'150 properly explained DSA questions',target:'150',due:'6 months',proof:''},{id:'m2',name:'Two deployed projects with tests',target:'2',due:'6 months',proof:''},{id:'m3',name:'Five-minute English interview conversation',target:'5 minutes',due:'6 months',proof:''},{id:'m4',name:'Complete Python Backend Internship',target:'Internship completed',due:'1 year',proof:''},{id:'m5',name:'Build a GCP / BigQuery data pipeline',target:'1 project',due:'1 year',proof:''},{id:'m6',name:'Backend or Data Engineering role',target:'Role secured',due:'2 years',proof:''}]};
