let page='home';
function save(){S.lastSavedAt=new Date().toLocaleString();let l=S.profile.level;S.profile.rank=l>=18?'S':l>=12?'A':l>=8?'B':l>=5?'C':l>=3?'D':'E';try{localStorage.setItem('ascend-v1',JSON.stringify(S))}catch{toast('Browser storage is full. Export a backup and remove old records.')}updateHeader()}function toast(m){let t=$('#toast');t.textContent=m;t.classList.remove('hidden');setTimeout(()=>t.classList.add('hidden'),2200)}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function xpNeed(l=S.profile.level){return 100+(l-1)*35}function gain(n,why){S.profile.xp+=n;while(S.profile.xp>=xpNeed()){S.profile.xp-=xpNeed();S.profile.level++;S.skillPoints=(S.skillPoints||0)+1;toast('Level up! You reached level '+S.profile.level+' · +1 Skill Point')}S.logs.push({date:today(),text:why,xp:n});save()}
function updateHeader(){let p=S.profile;$('#rankPill').textContent=p.rank+'-RANK · LVL '+p.level;$('#datePill').textContent=new Date().toLocaleDateString(undefined,{month:'short',day:'numeric'});let n=navItems.find(x=>x[0]===page);$('#pageTitle').textContent=n?.[2]||'Dashboard';$('#eyebrow').textContent='PLAYER TERMINAL';$('#pageSub').textContent=page==='home'?'Every small action counts.':'Build your system, one deliberate action at a time.'}
function go(p){page=p;render()}function nav(){let html=navItems.map(([id,ic,n])=>`<button class="${page===id?'active':''}" aria-current="${page===id?'page':'false'}" data-go="${id}">${ic} &nbsp;${n}</button>`).join('');$('#nav').innerHTML=html;$('#mobileNav').innerHTML=navItems.map(([id,ic,n])=>`<button class="${page===id?'active':''}" data-go="${id}">${ic}<br>${n}</button>`).join('');document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go))}
const card=(c,cl='span6')=>`<section class="card ${cl}">${c}</section>`,bar=(v,max)=>`<div class="bar"><i style="width:${Math.max(0,Math.min(100,max?100*v/max:0))}%"></i></div>`,btn=(label,act,cls='')=>`<button type="button" class="btn ${cls}" data-act="${act}">${label}</button>`;
function habitScheduleDays(h){return Array.isArray(h.days)&&h.days.length?[...new Set(h.days.filter(d=>Number.isInteger(d)&&d>=0&&d<=6))]:[0,1,2,3,4,5,6]}
function habitScheduledOn(h,date=today()){const day=new Date(date+'T12:00:00').getDay();return habitScheduleDays(h).includes(day)}
function habitScheduleText(h){const days=habitScheduleDays(h),names=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];return days.length===7?'Every day':days.length===5&&[1,2,3,4,5].every(x=>days.includes(x))?'Weekdays':days.length===2&&[0,6].every(x=>days.includes(x))?'Weekends':days.map(x=>names[x]).join(', ')}
function dashboard(){let p=S.profile,done=S.workouts.filter(w=>w.date===today()).length,hab=S.habits.filter(h=>habitScheduledOn(h)&&((S.habitLogs[today()]||[]).includes(h.id))).length;return `<div class="grid">${!p.onboarded?card(`<div class="eyebrow">FIRST-TIME SETUP</div><h2>Set up your character</h2><p class="muted">Choose a display name and a realistic starting plan. You can change everything later.</p><form id="onboardingForm"><div class="formgrid"><label>Player name<input class="field" name="name" value="${esc(p.name)}" required></label><label>Primary goal<select class="field" name="goal"><option>Build consistency</option><option>General fitness</option><option>Strength</option><option>Muscle building</option><option>Cardio & stamina</option><option>Mobility & movement</option></select></label><label>Experience<select class="field" name="level"><option>Beginner</option><option>Intermediate</option><option>Advanced</option></select></label><label>Equipment<select class="field" name="equipment"><option>Bodyweight only</option><option>Dumbbells + bodyweight</option><option>Gym access</option></select></label><label>Training days<select class="field" name="days"><option>2</option><option selected>3</option><option>4</option><option>5</option></select></label><label>Session duration<select class="field" name="duration"><option>20</option><option selected>30</option><option>45</option><option>60</option></select></label></div><label><input type="checkbox" name="createProgram" checked> Create my starter program now</label><div class="actions"><button class="btn primary">Save setup</button>${btn('Skip for now','skip-onboarding','ghost')}</div></form><p class="muted">Plans are general templates, not medical advice. Choose comfortable movements and rest whenever needed.</p>`,'span12'):''}${card(`<div class="eyebrow">WELCOME BACK, ${esc(p.name).toUpperCase()}</div><div class="row"><div><h2>${esc(p.name)}</h2><div class="muted">${esc(p.title)} · ${esc(p.goal)}</div><div class="big cyan">LEVEL ${p.level}</div><div class="xp">${p.xp} / ${xpNeed()} XP to next level</div>${bar(p.xp,xpNeed())}</div><div class="rank">${p.rank}</div></div><div class="actions">${btn('Log workout','new-workout','primary')}${btn('Plan today','execution')}</div>`,'span8')}${card(`<div class="label">TODAY'S MOMENTUM</div><div class="row"><div><div class="stat">${done}</div><small class="muted">Sessions</small></div><div><div class="stat">${hab}/${S.habits.length}</div><small class="muted">Habits</small></div><div><div class="stat">${S.tasks.filter(t=>t.date===today()&&t.done).length}</div><small class="muted">Tasks done</small></div></div><p class="muted">A lighter day still counts. Choose a pace you can recover from.</p>`,'span4')}${card(`<div class="sectionhead"><h3>Daily Quests</h3>${btn('View all','quests','ghost')}</div>${S.quests.slice(0,3).map(q=>`<div class="item"><div class="grow"><b>${esc(q.name)}</b><small>${esc(q.desc)}</small></div><span class="badge">+${q.xp} XP</span></div>`).join('')}`,'span6')}${card(`<div class="sectionhead"><h3>Quick Habits</h3>${btn('Manage','habits','ghost')}</div>${S.habits.slice(0,4).map(h=>`<div class="item"><div class="grow">${esc(h.name)}<small>${esc(habitScheduleText(h))}</small></div>${habitScheduledOn(h)?`<input aria-label="Complete ${esc(h.name)}" type="checkbox" data-habit="${h.id}" ${(S.habitLogs[today()]||[]).includes(h.id)?'checked':''}>`:'<span class="muted">Not scheduled</span>'}</div>`).join('')}`,'span6')}${card(`<h3>Recent Activity</h3>${S.logs.slice(-5).reverse().map(l=>`<div class="item"><div class="grow">${esc(l.text)}<small>${esc(l.date)}</small></div><span class="badge">+${l.xp} XP</span></div>`).join('')||'<p class="muted">Your journey starts with one small action.</p>'}`,'span12')}</div>`}
function workoutLegacy(){return `<div class="grid">${card(`<h2>Log a workout</h2><form id="workoutForm"><div class="formgrid"><label>Session name<input class="field" name="name" value="Strength session" required></label><label>Date<input class="field" type="date" name="date" value="${today()}" required></label><label>Duration (minutes)<input class="field" type="number" name="duration" min="1" value="30"></label><label>Effort<select class="field" name="effort"><option>Easy</option><option selected>Moderate</option><option>Hard</option></select></label></div><label>Exercises</label><div id="exerciseRows"><div class="formgrid exrow"><select class="field" name="exercise">${exercises.map(e=>`<option>${e.name}</option>`).join('')}</select><input class="field" name="sets" type="number" min="1" value="3" placeholder="Sets"><input class="field" name="reps" type="number" min="1" value="10" placeholder="Reps"><input class="field" name="weight" type="number" min="0" step="0.5" value="0" placeholder="Weight kg"></div></div><div class="actions">${btn('+ Add exercise','add-ex','ghost')}<button class="btn primary" type="submit">Save session · earn XP</button></div></form>`,'span7')}${card(`<h3>Exercise Library</h3><input class="field" id="exSearch" placeholder="Search name, group or equipment…"><div class="formgrid"><label>Movement group<select class="field" id="exGroupFilter"><option value="">All groups</option>${[...new Set(exercises.map(e=>e.group))].map(x=>`<option>${esc(x)}</option>`).join('')}</select></label><label>Equipment<select class="field" id="exEquipmentFilter"><option value="">All equipment</option>${[...new Set(exercises.map(e=>e.equipment))].map(x=>`<option>${esc(x)}</option>`).join('')}</select></label></div><div class="list" id="exerciseList">${exerciseList(exercises)}</div>`,'span5')}${card(`<h3>Session history</h3>${S.workouts.slice().reverse().slice(0,12).map(w=>`<div class="item"><div class="grow"><b>${esc(w.name)}</b><small>${esc(w.date)} · ${w.duration} min · ${esc(w.effort)}</small><small>${w.items.map(i=>esc(i.name)+' · '+i.sets+' sets × '+(i.reps||'—')+' reps'+(i.weight?' @ '+i.weight+' kg':'')).join(', ')}</small></div><span class="badge">${w.xp} XP</span></div>`).join('')||'<p class="muted">No sessions yet.</p>'}`,'span12')}</div>`}
function exerciseList(a){return a.map(e=>`<div class="item"><div class="grow"><b>${esc(e.name)}</b><small>${esc(e.group)} · ${esc(e.equipment)} · ${esc(e.level||'General')}</small><small>${esc(e.instructions||'Use controlled movement and comfortable range.')}</small></div></div>`).join('')}
function questEligible(q){if(q.type==='workout')return S.workouts.some(w=>w.date===today());if(q.type==='habit')return (S.habitLogs[today()]||[]).length>0;if(q.type==='plan')return !!S.personal?.days?.[today()]?.done?.review||!!S.reviews?.[today()]||S.tasks.some(t=>t.date===today()&&t.done);return true}
function quests(){return `<div class="grid">${card(`<h2>Quest Board</h2><p class="muted">Choose meaningful actions. Missed days do not erase progress.</p>${S.quests.map(q=>`<div class="item"><div class="grow"><b>${esc(q.name)}</b><small>${esc(q.desc)}</small></div><span class="badge">+${q.xp} XP</span>${(S.questDone[today()]||[]).includes(q.id)?'<span class="green">Done</span>':questEligible(q)?btn('Claim','quest:'+q.id,'primary'):'<span class="muted">Complete the action first</span>'}</div>`).join('')}`,'span8')}${card(`<h3>Create a quest</h3><form id="questForm"><label>Name<input class="field" name="name" required></label><label>Description<input class="field" name="desc"></label><label>XP reward<input class="field" name="xp" type="number" min="5" max="30" value="20"></label><button class="btn primary">Add quest</button></form>`,'span4')}</div>`}
function habits(){const dayNames=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];return `<div class="grid">${card(`<h2>Habit Garden</h2><p class="muted">Set the days that suit your real routine. Unscheduled days are not missed days. No streak resets or guilt mechanics.</p>${S.habits.map(h=>{const scheduled=habitScheduledOn(h),done=(S.habitLogs[today()]||[]).includes(h.id),days=habitScheduleDays(h);return `<div class="item">${scheduled?`<input aria-label="Complete ${esc(h.name)}" type="checkbox" data-habit="${h.id}" ${done?'checked':''}>`:'<span class="badge">REST</span>'}<div class="grow"><b>${esc(h.name)}</b><small>${esc(habitScheduleText(h))} · ${scheduled?(done?'Completed today':'Planned today'):'Not scheduled today'}</small></div>${btn('Delete','delhabit:'+h.id,'danger')}</div><details class="item details"><summary>Edit schedule · ${esc(h.name)}</summary><form data-habit-schedule="${h.id}"><div class="formgrid">${dayNames.map((n,i)=>`<label class="item"><input type="checkbox" name="days" value="${i}" ${days.includes(i)?'checked':''}> ${n}</label>`).join('')}</div><button class="btn primary">Save schedule</button></form></details>`}).join('')||'<p class="muted">Add a habit to begin.</p>'}`,'span8')}${card(`<h3>Plant a habit</h3><form id="habitForm"><label>Habit name<input class="field" name="name" placeholder="e.g. 10-minute walk" required></label><p class="muted">Choose active days. All seven are selected by default.</p><div class="formgrid">${dayNames.map((n,i)=>`<label class="item"><input type="checkbox" name="days" value="${i}" checked> ${n}</label>`).join('')}</div><button class="btn primary">Add habit</button></form><p class="muted">Start small enough that it fits an ordinary day. A rest day is not a missed habit.</p>`,'span4')}</div>`}

function execution(){return `<div class="grid">${card(`<h2>Personal Execution System</h2><p class="muted">Turn intention into a manageable next action. Keep the plan humane and adjustable.</p><form id="taskForm"><div class="formgrid"><label>Next action<input class="field" name="name" placeholder="The one thing to move forward" required></label><label>When<input class="field" name="date" type="date" value="${today()}"></label><label>Priority<select class="field" name="priority"><option>Important</option><option>Normal</option><option>Optional</option></select></label><label>Focus estimate (min)<input class="field" name="minutes" type="number" min="5" value="25"></label></div><button class="btn primary">Add to plan</button></form><h3 style="margin-top:22px">Action list</h3>${S.tasks.filter(t=>t.date===today()).map(t=>`<div class="item"><input type="checkbox" data-task="${t.id}" ${t.done?'checked':''}><div class="grow"><b style="${t.done?'text-decoration:line-through;opacity:.6':''}">${esc(t.name)}</b><small>${t.priority} · ${t.minutes} min</small></div>${btn('×','deltask:'+t.id,'danger')}</div>`).join('')||'<p class="muted">No actions planned for today.</p>'}`,'span8')}${card(`<h3>Daily reset</h3><ul class="muted"><li>Choose one meaningful priority.</li><li>Break it into a visible next action.</li><li>Use a short focus block, then pause.</li><li>Review without judging yourself.</li></ul><h3>End-of-day review</h3><textarea class="field" id="review" rows="4" placeholder="What worked? What should change tomorrow?">${esc(S.reviews?.[today()]||'')}</textarea>${btn('Save reflection','save-review','primary')}`,'span4')}</div>`}
function recovery(){let r=S.recovery.find(x=>x.date===today())||{};return `<div class="grid">${card(`<h2>Recovery Check-in</h2><p class="muted">Recovery is part of training. Choose rest or gentle movement whenever needed.</p><form id="recoveryForm"><div class="formgrid"><label>Sleep (hours)<input class="field" name="sleep" type="number" min="0" max="24" step=".5" value="${r.sleep??8}"></label><label>Energy (1–5)<input class="field" name="energy" type="number" min="1" max="5" value="${r.energy??3}"></label><label>Soreness (1–5)<input class="field" name="soreness" type="number" min="1" max="5" value="${r.soreness??2}"></label><label>Mood<select class="field" name="mood"><option ${r.mood==='Good'?'selected':''}>Good</option><option ${r.mood==='Okay'?'selected':''}>Okay</option><option ${r.mood==='Low'?'selected':''}>Low</option></select></label></div><label>Notes<textarea class="field" name="notes" rows="3">${esc(r.notes||'')}</textarea></label><button class="btn primary">Save check-in</button></form>`,'span7')}${card(`<h3>Recovery principles</h3><div class="item"><div class="grow"><b>Low energy?</b><small>Reduce load, shorten the session, or rest.</small></div></div><div class="item"><div class="grow"><b>Persistent pain?</b><small>Stop the painful activity and seek qualified clinical advice.</small></div></div><div class="item"><div class="grow"><b>Rest day</b><small>Rest is productive. No XP penalty.</small></div></div>`,'span5')}${card(`<h3>Recent check-ins</h3>${S.recovery.slice().reverse().slice(0,7).map(x=>`<div class="item"><div class="grow">${x.date}<small>Sleep ${x.sleep}h · Energy ${x.energy}/5 · Soreness ${x.soreness}/5</small></div></div>`).join('')||'<p class="muted">No check-ins recorded.</p>'}`,'span12')}</div>`}
const skillData=[['Foundation','Complete 3 workouts',3],['Consistency','Log 7 workouts',7],['Resilience','Complete 5 recovery check-ins',5],['Focus','Complete 10 planned actions',10],['Explorer','Try 8 different exercises',8],['Veteran','Reach level 10',10]];
function skills(){return `<div class="grid">${card(`<h2>Skill Tree</h2><p class="muted">Unlocks celebrate real practice; no purchase or paywall required.</p>${skillData.map((s,i)=>{let n=[S.workouts.length,S.workouts.length,S.recovery.length,S.tasks.filter(t=>t.done).length,new Set(S.workouts.flatMap(w=>w.items.map(x=>x.name))).size,S.profile.level][i],ok=n>=s[2]||S.skills.includes(i);return `<div class="item"><div class="grow"><b>${s[0]}</b><small>${s[1]} · ${Math.min(n,s[2])}/${s[2]}</small>${bar(n,s[2])}</div><span class="badge">${ok?'UNLOCKED':'LOCKED'}</span>${ok&&!S.skills.includes(i)?btn('Unlock','skill:'+i):''}</div>`}).join('')}`,'span8')}${card(`<h3>Progression rules</h3><p class="muted">XP comes from workouts, habits, quests and planned actions. Levels are additive. Ranks are cosmetic milestones, not a measure of personal worth.</p>`,'span4')}</div>`}
function achievements(){let list=[['First Session',S.workouts.length>=1],['Five Sessions',S.workouts.length>=5],['Habit Builder',S.habitLogs&&Object.values(S.habitLogs).flat().length>=10],['Planner',S.tasks.some(t=>t.done)],['Recovery Minded',S.recovery.length>=3],['Level Five',S.profile.level>=5]];return `<div class="grid">${card(`<h2>Achievements</h2>${list.map(([n,ok])=>`<div class="item"><div class="grow"><b>${n}</b><small>${ok?'Milestone reached':'Keep going at your own pace'}</small></div><span class="badge">${ok?'✦ EARNED':'LOCKED'}</span></div>`).join('')}`,'span8')}${card(`<h3>Titles</h3><p class="muted">${esc(S.profile.title)}</p>${btn('Equip Rising Beginner','title:Rising Beginner','ghost')}`,'span4')}</div>`}
function inventory(){return `<div class="grid">${card(`<h2>Inventory</h2><p class="muted">Cosmetic keepsakes earned through milestones.</p>${S.inventory.map(i=>`<div class="item"><div class="grow">◇ ${esc(i)}</div><span class="badge">OWNED</span></div>`).join('')}`,'span8')}${card(`<h3>Collection note</h3><p class="muted">Inventory items do not affect workout performance. This system is intentionally cosmetic.</p>`,'span4')}</div>`}
function spellbook(){return `<div class="grid">${card(`<h2>Spellbook · Saved Routines</h2>${S.spells.map(s=>`<div class="item"><div class="grow"><b>${esc(s.name)}</b><small>${s.items.map(i=>esc(i.name)+' × '+i.sets).join(', ')}</small></div>${btn('Use','spell:'+s.id,'ghost')}${btn('×','delspell:'+s.id,'danger')}</div>`).join('')||'<p class="muted">Save a workout as a reusable routine after logging it.</p>'}`,'span8')}${card(`<h3>How to save</h3><p class="muted">Log a session in Workouts, then choose “Save last session to Spellbook”.</p>${btn('Go to Workouts','workout','primary')}${btn('Save last session to Spellbook','save-spell','ghost')}`,'span4')}</div>`}
function analytics(){let total=S.workouts.length,mins=S.workouts.reduce((a,w)=>a+w.duration,0),vol=S.workouts.reduce((a,w)=>a+w.items.reduce((n,i)=>n+i.sets,0),0),days=new Set(S.workouts.map(w=>w.date)).size;let weekly=Array.from({length:7},(_,i)=>{let d=new Date();d.setDate(d.getDate()-6+i);let ds=d.toISOString().slice(0,10);return {d:d.toLocaleDateString(undefined,{weekday:'short'}),n:S.workouts.filter(w=>w.date===ds).length}});return `<div class="grid">${card(`<h2>Progress Overview</h2><div class="row"><div><div class="stat">${total}</div><small class="muted">Sessions</small></div><div><div class="stat">${mins}</div><small class="muted">Minutes</small></div><div><div class="stat">${vol}</div><small class="muted">Total sets</small></div><div><div class="stat">${days}</div><small class="muted">Active days</small></div></div>`,'span12')}${card(`<h3>Last 7 days</h3>${weekly.map(x=>`<div class="row"><span>${x.d}</span><div style="width:75%">${bar(x.n,Math.max(3,...weekly.map(y=>y.n)))}</div><b>${x.n}</b></div>`).join('')}`,'span7')}${card(`<h3>Personal records</h3>${Object.keys(S.records).length?Object.entries(S.records).map(([k,v])=>`<div class="item"><div class="grow">${esc(k)}</div><b>${esc(v)}</b></div>`).join(''):'<p class="muted">Record your own milestones in a workout note. Structured lift PR tracking is planned for a later release.</p>'}`,'span5')}</div>`}
function profile(){let p=S.profile;return `<div class="grid">${card(`<h2>Character Profile</h2><form id="profileForm"><label>Player name<input class="field" name="name" value="${esc(p.name)}"></label><label>Character title<input class="field" name="title" value="${esc(p.title)}"></label><label>Primary goal<input class="field" name="goal" value="${esc(p.goal)}"></label><div class="formgrid"><label>Height (cm)<input class="field" name="height" type="number" value="${esc(p.height)}"></label><label>Weight (${S.settings.units})<input class="field" name="weight" type="number" step=".1" value="${esc(p.weight)}"></label></div><button class="btn primary">Save character</button></form>`,'span6')}${card(`<h3>Character stats</h3><div class="row"><span>Level</span><b>${p.level}</b></div>${bar(p.xp,xpNeed())}<div class="row"><span>Rank</span><b class="gold">${p.rank}</b></div><div class="row"><span>Total XP earned</span><b>${S.logs.reduce((n,l)=>n+l.xp,0)}</b></div><p class="muted">Your character is a reflection of your journey, not a judgment of your body.</p>`,'span6')}</div>`}
function settings(){return `<div class="grid">${card(`<h2>Settings & Data</h2><p class="muted">Your data is stored locally in this browser. Export a backup before changing devices or clearing browser data.</p><div class="actions">${btn('Export JSON backup','export','primary')}${btn('Export encrypted backup','export-encrypted','ghost')}<label class="btn">Import backup<input type="file" id="importFile" accept=".json,.ascendbackup,application/json,application/octet-stream" hidden></label>${btn('Reset local data','reset','danger')}</div><label>Weight units<select class="field" id="units"><option ${S.settings.units==='kg'?'selected':''}>kg</option><option ${S.settings.units==='lb'?'selected':''}>lb</option></select></label><h3>Privacy & local storage</h3><p class="muted">No account, analytics beacon, or remote server is used. All profile and activity data stays in this browser. Browser storage is not encrypted as a secure vault; use an encrypted backup for portable copies and protect access to this device.</p><p class="muted">Approximate current data size: ${Math.max(1,Math.round(new Blob([JSON.stringify(S)]).size/1024))} KB. This is an estimate, not the browser quota.</p>`,'span7')}${card(`<h3>About Ascend</h3><div class="big cyan">ASCEND</div><p class="muted">An original anime-inspired fitness RPG and personal execution system. Offline-first. Designed for sustainable habits and user agency.</p><span class="badge">VERSION 1.4 · OFFLINE PWA</span>`,'span5')}</div>`}

function nextCoreSubject(date=today()){
 const order=['DBMS','Operating Systems','Computer Networks'];
 const prior=Object.keys(S.personal.days||{}).filter(k=>k<date).sort().reverse().map(k=>S.personal.days[k]).find(x=>x.done?.core&&order.includes(x.coreSubject));
 return prior?order[(order.indexOf(prior.coreSubject)+1)%order.length]:'DBMS';
}
function personalDay(date=today()){
 return S.personal.days[date]||{date,done:{},wakeTarget:S.personal.wakeTarget||'',wakeTime:'',phoneFree:false,
 commuteType:'Shadowing',commuteMinutes:0,commuteTotalMinutes:0,commuteSafe:false,
 q1:'',q2:'',q1Solution:'',q2Solution:'',q1Topic:'',q2Topic:'',q1Difficulty:'Easy',q2Difficulty:'Easy',q1Minutes:0,q2Minutes:0,q1Hint:'No',q2Hint:'No',q1Revision:false,q2Revision:false,q1Revised:false,q2Revised:false,dsaExplained:false,
 coreSubject:nextCoreSubject(date),coreTopic:'',coreMinutes:0,
 sprintFeature:'',sprintCommit:'',sprintMinutes:0,sprintPushed:false,
 englishMinutes:0,englishRecording:'',englishListenedBack:false,
 workoutType:'Bodyweight',workoutMinutes:0,workoutRecovery:false,recoveryAction:'',recoveryMinutes:0,
 reviewMinutes:0,review1:'',review2:'',review3:'',reviewNotes:'',examSubject:'',examStudyMinutes:0,examPYQs:0,examPaperAttempted:false,examMistakeReview:'',examMistakeMinutes:0};
}
const personalTasks=[['wake','Wake-up + phone control','Fixed target + actual wake time + first 20 minutes phone-free'],['commute','Commute practice','Shadowing OR flashcards; record actual commute and practice minutes'],['dsa','DSA · 2 questions','Two Python solutions, topics, difficulty, time, hint use, revision and explanation'],['core','Core CS','One slot; normal rotation DBMS → OS → CN'],['sprint','Sprint / build','60+ minutes, one feature, one commit and GitHub push'],['english','English practice','15 minutes + recording + listen back'],['workout','Workout','20-minute session or a documented 30-minute recovery action'],['review','Night review','5-minute review and tomorrow’s top 3']];
function execution(){
 const d=personalDay(),isExam=!!S.personal.examMode,dates=Object.keys(S.personal.days||{}).sort();
 const streak=(()=>{let n=0,dt=new Date();for(let i=0;i<60;i++){let k=`${dt.getFullYear()}-${String(dt.getMonth()+1).padStart(2,'0')}-${String(dt.getDate()).padStart(2,'0')}`,v=S.personal.days[k];if(!v||Object.values(v.done||{}).filter(Boolean).length===0)break;n++;dt.setDate(dt.getDate()-1)}return n})();
 const prior1=new Date();prior1.setDate(prior1.getDate()-1);const prior2=new Date();prior2.setDate(prior2.getDate()-2);
 const key=x=>`${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`;
 const missed2=[key(prior1),key(prior2)].every(k=>!!S.personal.days[k]&&Object.values(S.personal.days[k].done||{}).filter(Boolean).length===0);
 const recovery=missed2&&!isExam,count=Object.values(d.done||{}).filter(Boolean).length;
 const tasks=isExam?[['exam','Exam subject + PYQs','Current exam subject, PYQs and 10-minute mistake review']]:personalTasks;
 const revisionItems=Object.entries(S.personal.days||{}).flatMap(([date,x])=>[['q1',x.q1,x.q1Topic,x.q1Revision],['q2',x.q2,x.q2Topic,x.q2Revision]].filter(v=>v[3]&&v[1]).map(v=>({date,problem:v[1],topic:v[2]||'Topic not entered'}))).slice(-12).reverse();
 return `<div class="grid">
 ${card(`<div class="row"><div><div class="eyebrow">PERSONAL COMMAND CENTER</div><h2>One daily record. Real outputs.</h2><p class="muted">One consolidated record for study, career, fitness and review. No backlog and no guilt.</p></div><span class="badge">${isExam?'EXAM MODE':recovery?'RECOVERY MODE':'NORMAL MODE'}</span></div><div class="row"><div><div class="big cyan">${count}/${isExam?1:8}</div><small class="muted">Tasks completed today</small></div><div><div class="big">${streak}</div><small class="muted">Recorded active days · no punishment</small></div><div><div class="big">${dates.length}</div><small class="muted">Days with saved records</small></div></div>${bar(count,isExam?1:8)}<div class="actions">${btn(isExam?'Exit Exam Mode':'Activate Exam Crunch Mode','toggle-exam',isExam?'danger':'primary')}${btn('Weekly review','weekly-review','ghost')}${btn('Career milestones','career','ghost')}</div>`,'span12')}
 ${recovery?card(`<h3 class="gold">Gentle comeback suggestion</h3><p>Two previous days have recorded zero progress. Choose one useful 30-minute action today. This does not create a backlog or erase history.</p>${btn('Use a 30-minute recovery day','recovery-day','primary')}`,'span12'):''}
 ${isExam?card(`<h3>Exam Crunch Mode</h3><p class="muted">Build work and non-exam targets are paused. Focus on the current paper, PYQs and a 10-minute mistake review. Previous progress is preserved.</p><form id="examForm"><label>Current exam subject<input class="field" name="examSubject" value="${esc(d.examSubject)}" placeholder="e.g. Operating Systems" required></label><label>PYQs completed today<input class="field" type="number" min="0" name="examPYQs" value="${d.examPYQs||0}"></label><label>10-minute mistake review<textarea class="field" name="examMistakeReview" rows="3">${esc(d.examMistakeReview)}</textarea></label><button class="btn primary">Save exam record</button></form>`,'span12'):card(`<h3>Daily execution record</h3><p class="muted">Done / Not Done only. Each item is complete only when its evidence rule is satisfied. You can save partial notes without earning a completion.</p><form id="executionForm">
 <h3>Wake-up & commute</h3><p class="muted">Practice shadowing or use the offline flashcards deck only when stationary or travelling as a passenger. ${btn('Open offline flashcards','flashcards','ghost')}</p><div class="formgrid"><label>Fixed wake-up target<input class="field" type="time" name="wakeTarget" value="${esc(d.wakeTarget||S.personal.wakeTarget||'')}"></label><label>Actual wake-up time<input class="field" type="time" name="wakeTime" value="${esc(d.wakeTime)}"></label><label>Commute practice<select class="field" name="commuteType"><option ${d.commuteType==='Shadowing'?'selected':''}>Shadowing</option><option ${d.commuteType==='Flashcards'?'selected':''}>Flashcards</option></select></label><label>Total commute (minutes)<input class="field" type="number" min="0" name="commuteTotalMinutes" value="${d.commuteTotalMinutes||0}"></label><label>Practice minutes<input class="field" type="number" min="0" name="commuteMinutes" value="${d.commuteMinutes||0}"></label></div>
 <div class="item"><label><input type="checkbox" name="phoneFree" ${d.phoneFree?'checked':''}> First 20 minutes phone-free</label></div>
 <h3>DSA · two properly explained problems</h3><p class="muted">Record the problem, topic, difficulty, time, whether a hint was used, and whether it needs revision. Enter your Python solution or a private file reference.</p><div class="formgrid">
 <label>Problem 1 name / ID<input class="field" name="q1" value="${esc(d.q1)}"></label><label>Problem 2 name / ID<input class="field" name="q2" value="${esc(d.q2)}"></label>
 <label>Problem 1 topic<input class="field" name="q1Topic" value="${esc(d.q1Topic)}"></label><label>Problem 2 topic<input class="field" name="q2Topic" value="${esc(d.q2Topic)}"></label>
 <label>Problem 1 difficulty<select class="field" name="q1Difficulty">${['Easy','Medium','Hard'].map(x=>`<option ${d.q1Difficulty===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Problem 2 difficulty<select class="field" name="q2Difficulty">${['Easy','Medium','Hard'].map(x=>`<option ${d.q2Difficulty===x?'selected':''}>${x}</option>`).join('')}</select></label>
 <label>Problem 1 minutes<input class="field" name="q1Minutes" type="number" min="1" value="${d.q1Minutes||0}"></label><label>Problem 2 minutes<input class="field" name="q2Minutes" type="number" min="1" value="${d.q2Minutes||0}"></label>
 <label>Hint used for problem 1?<select class="field" name="q1Hint"><option ${d.q1Hint==='No'?'selected':''}>No</option><option ${d.q1Hint==='Yes'?'selected':''}>Yes</option></select></label><label>Hint used for problem 2?<select class="field" name="q2Hint"><option ${d.q2Hint==='No'?'selected':''}>No</option><option ${d.q2Hint==='Yes'?'selected':''}>Yes</option></select></label>
 <label>Python solution / notes — problem 1<textarea class="field" name="q1Solution" rows="3">${esc(d.q1Solution)}</textarea></label><label>Python solution / notes — problem 2<textarea class="field" name="q2Solution" rows="3">${esc(d.q2Solution)}</textarea></label></div>
 <div class="formgrid"><label><input type="checkbox" name="q1Revision" ${d.q1Revision?'checked':''}> Add problem 1 to revision queue</label><label><input type="checkbox" name="q2Revision" ${d.q2Revision?'checked':''}> Add problem 2 to revision queue</label></div><div class="item"><label><input type="checkbox" name="dsaExplained" ${d.dsaExplained?'checked':''}> Explained both solutions without looking at notes</label></div>
 <h3>Core CS · DBMS → OS → CN</h3><div class="formgrid"><label>Subject<select class="field" name="coreSubject">${['DBMS','Operating Systems','Computer Networks','Exam subject'].map(x=>`<option ${d.coreSubject===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Topic studied<input class="field" name="coreTopic" value="${esc(d.coreTopic)}"></label><label>Focused study minutes<input class="field" type="number" min="0" name="coreMinutes" value="${d.coreMinutes||0}"></label></div><p class="muted">The next new day defaults to the next normal subject after the last completed Core CS record. Exam mode overrides the normal rotation. Only practise during a commute when it is safe; never read a screen while driving or crossing roads.</p>
 <h3>Project sprint</h3><div class="formgrid"><label>Feature delivered<input class="field" name="sprintFeature" value="${esc(d.sprintFeature)}"></label><label>Git commit / GitHub URL<input class="field" name="sprintCommit" value="${esc(d.sprintCommit)}"></label><label>Focused build minutes<input class="field" type="number" min="0" name="sprintMinutes" value="${d.sprintMinutes||0}"></label></div><div class="item"><label><input type="checkbox" name="sprintPushed" ${d.sprintPushed?'checked':''}> Feature committed and pushed to GitHub</label></div>
 <h3>English speaking</h3><div class="formgrid"><label>Practice minutes<input class="field" type="number" min="0" name="englishMinutes" value="${d.englishMinutes||0}"></label><label>Recording file name / private reference<input class="field" name="englishRecording" value="${esc(d.englishRecording)}" placeholder="Recorded using phone voice recorder"></label></div><div class="item"><label><input type="checkbox" name="englishListenedBack" ${d.englishListenedBack?'checked':''}> Listened back to the recording</label></div>
 <h3>Fitness & recovery</h3><div class="formgrid"><label>Workout type<input class="field" name="workoutType" value="${esc(d.workoutType)}"></label><label>Workout minutes<input class="field" type="number" min="0" name="workoutMinutes" value="${d.workoutMinutes||0}"></label><label>Recovery action (when not training)<input class="field" name="recoveryAction" value="${esc(d.recoveryAction)}" placeholder="e.g. 30-minute walk / mobility / reset"></label><label>Recovery action minutes<input class="field" type="number" min="0" name="recoveryMinutes" value="${d.recoveryMinutes||0}"></label></div><div class="item"><label><input type="checkbox" name="workoutRecovery" ${d.workoutRecovery?'checked':''}> Mark today as a planned recovery day</label><span class="muted">Rest is valid; recovery action requires 30 minutes</span></div>
 <h3>Night review · target 5 minutes</h3><div class="formgrid"><label>Review minutes<input class="field" name="reviewMinutes" type="number" min="0" value="${d.reviewMinutes||0}"></label><label>Tomorrow priority 1<input class="field" name="review1" value="${esc(d.review1)}"></label><label>Tomorrow priority 2<input class="field" name="review2" value="${esc(d.review2)}"></label><label>Tomorrow priority 3<input class="field" name="review3" value="${esc(d.review3)}"></label></div><label>Daily review notes<textarea class="field" name="reviewNotes" rows="3">${esc(d.reviewNotes)}</textarea></label><button class="btn primary">Save today’s single record</button></form>`,'span12')}
 ${card(`<h3>Today’s status</h3>${tasks.map(([id,n])=>`<div class="item"><div class="grow"><b>${n}</b><small>${id==='dsa'?'Two distinct problems + topic + difficulty + time + solution notes + explanation':id==='sprint'?'60+ minutes + feature + commit + push':id==='english'?'15 min + recording reference + listened back':id==='workout'?'20 min workout OR planned recovery + 30-min action':id==='core'?'Subject + topic + at least 25 study minutes':id==='commute'?'Shadowing or flashcards + positive practice minutes':id==='review'?'5 minutes + tomorrow’s three priorities':id==='wake'?'Fixed target + actual wake time + phone-free checkbox':'Exam study + PYQs / review'}</small></div><span class="badge">${d.done?.[id]?'DONE':'NOT DONE'}</span></div>`).join('')}`,'span12')}
 ${card(`<h3>Recent daily records</h3>${dates.slice(-7).reverse().map(k=>{let v=S.personal.days[k],n=Object.values(v.done||{}).filter(Boolean).length,den=v.mode==='exam'?1:8;return `<div class="item"><div class="grow"><b>${k}</b><small>${n}/${den} tasks recorded${v.mode==='exam'?' · Exam mode':''}</small></div><span class="badge">${Math.round(n/den*100)}%</span></div>`}).join('')||'<p class="muted">Your first saved day will appear here.</p>'}`,'span6')}${card(`<h3>DSA revision queue</h3>${revisionItems.length?revisionItems.map(x=>`<div class="item"><div class="grow"><b>${esc(x.problem)}</b><small>${esc(x.topic)} · added ${esc(x.date)}</small></div></div>`).join(''):'<p class="muted">Mark a problem for revision in the daily record and it will appear here.</p>'}`,'span6')}${card(`<h3>Execution rules</h3><ul class="muted"><li>One consolidated record; Done / Not Done only.</li><li>DSA requires two Python problems and explanation; hints and revision are tracked.</li><li>Build requires 60+ focused minutes, a feature, commit and push.</li><li>English requires a recording reference and listen-back confirmation.</li><li>Exam mode pauses non-exam work.</li><li>Recovery offers one 30-minute action; no backlog is created.</li><li>Missing historical days are unknown, never assumed failures.</li></ul>`,'span6')}</div>`;
}
function career(){let ms=S.personal.milestones||[];let days=Object.values(S.personal.days);let dsa=days.filter(d=>d.done?.dsa).length*2,build=days.filter(d=>d.done?.sprint).length,english=days.filter(d=>d.done?.english).length;return `<div class="grid">${card(`<h2>Career milestones</h2><div class="row"><div><div class="stat">${dsa}</div><small class="muted">DSA questions marked explained</small></div><div><div class="stat">${build}</div><small class="muted">Build days with commit evidence</small></div><div><div class="stat">${english}</div><small class="muted">English recording sessions</small></div></div><p class="muted">Track outcomes and attach evidence. Dates are targets, not guarantees.</p>${ms.map(m=>`<div class="item"><div class="grow"><b>${esc(m.name)}</b><small>Target: ${esc(m.target)} · Timeline: ${esc(m.due)}</small>${m.proof?`<small>Evidence: ${esc(m.proof)}</small>`:''}</div><span class="badge">${m.completed?'DONE':'IN PROGRESS'}</span></div>`).join('')}`,'span8')}${card(`<h3>Update milestone evidence</h3><form id="milestoneForm"><label>Milestone<select class="field" name="id">${ms.map(m=>`<option value="${m.id}">${esc(m.name)}</option>`).join('')}</select></label><label>Proof link / outcome<input class="field" name="proof" placeholder="GitHub, deployed URL, offer, etc."></label><label><input type="checkbox" name="completed"> Mark complete</label><button class="btn primary">Save milestone</button></form><p class="muted">Goals: placement, 150+ DSA, two tested deployments, interview English, backend internship, data pipeline and role progression.</p>`,'span4')}</div>`}
function weeklyReviewComplete(record,date=new Date()){return date.getDay()===0&&+record.reviewMinutes>=20&&!!String(record.wins||'').trim()&&!!String(record.gaps||'').trim()&&!!String(record.next||'').trim()}
function weeklyReview(){
 const keys=dateKeysLast7(),dates=keys.filter(k=>S.personal.days[k]);
 const sum=dates.reduce((n,k)=>n+Object.values(S.personal.days[k].done||{}).filter(Boolean).length,0);
 const target=dates.reduce((n,k)=>n+(S.personal.days[k].mode==='exam'?1:8),0);
 const weekStart=keys[0],history=Array.isArray(S.personal.weeklyReviews)?S.personal.weeklyReviews:[];
 const legacy=S.personal.weeklyReview||{};const r=history.find(x=>x.weekStart===weekStart)||(legacy.weekStart===weekStart||keys.includes(legacy.date)?legacy:{});
 const sunday=new Date().getDay()===0;
 const recent=history.slice().sort((a,b)=>String(b.weekStart).localeCompare(String(a.weekStart))).slice(0,6);
 return `<div class="grid">${card(`<h2>Weekly review</h2><div class="big cyan">${sum}/${target||0}</div><p class="muted">${dates.length} recorded days in this Monday-starting week. Missing dates are unknown, not failures.</p><p class="badge">${r.completed?'20-MINUTE REVIEW COMPLETE':sunday?'SUNDAY REVIEW NOT COMPLETE':'DRAFT · COMPLETE ON SUNDAY'}</p><p class="muted">The weekly review is intended for Sunday. You can save notes earlier, but it only counts as complete on Sunday after 20+ minutes and all reflection fields.</p><form id="weeklyForm"><label>Review duration (minutes; target 20)<input class="field" type="number" min="0" max="240" name="reviewMinutes" value="${esc(r.reviewMinutes??0)}"></label><label>What was completed?<textarea class="field" name="wins" rows="3" required>${esc(r.wins||'')}</textarea></label><label>What was not completed, and why?<textarea class="field" name="gaps" rows="3" required>${esc(r.gaps||'')}</textarea></label><label>Next week’s 3 priorities<textarea class="field" name="next" rows="3" required>${esc(r.next||'')}</textarea></label><button class="btn primary">Save weekly review</button></form>`,'span8')}${card(`<h3>Past weekly reviews</h3>${recent.map(x=>`<div class="item"><div class="grow"><b>Week of ${esc(x.weekStart||x.date||'—')}</b><small>${x.reviewMinutes||0} minutes · ${x.completed?'Complete':'Draft'}</small></div><span class="badge">${x.completed?'DONE':'DRAFT'}</span></div>`).join('')||'<p class="muted">Completed reviews will appear here.</p>'}<p class="muted">Keep the review practical: notice patterns, reduce friction and choose three realistic priorities.</p>`,'span4')}</div>`;
}




function render(){nav();updateHeader();let fn={home:dashboard,workout,quests,habits,execution,recovery,skills,achievements,inventory,spellbook,analytics,career,profile,planner,challenges,story,help,settings}[page]||dashboard;$('#view').innerHTML=fn();bind()}
function evaluateDailyRecord(d){
 const clean=v=>String(v??'').trim();
 const distinct=clean(d.q1).toLowerCase()!==clean(d.q2).toLowerCase();
 const validTime=v=>/^([01]\d|2[0-3]):[0-5]\d$/.test(String(v||''));
 return {
  wake:validTime(d.wakeTarget)&&validTime(d.wakeTime)&&!!d.phoneFree,
  commute:clean(d.commuteType)!==''&&+d.commuteMinutes>0&&+d.commuteTotalMinutes>=+d.commuteMinutes&&!!d.commuteSafe,
  dsa:!!clean(d.q1)&&!!clean(d.q2)&&distinct&&!!clean(d.q1Topic)&&!!clean(d.q2Topic)&&['Easy','Medium','Hard'].includes(d.q1Difficulty)&&['Easy','Medium','Hard'].includes(d.q2Difficulty)&&+d.q1Minutes>0&&+d.q2Minutes>0&&!!clean(d.q1Solution)&&!!clean(d.q2Solution)&&!!d.dsaExplained,
  core:!!clean(d.coreSubject)&&d.coreSubject===nextCoreSubject(today())&&!!clean(d.coreTopic)&&+d.coreMinutes>=25,
  sprint:!!clean(d.sprintFeature)&&!!clean(d.sprintCommit)&&+d.sprintMinutes>=60&&!!d.sprintPushed,
  english:+d.englishMinutes>=15&&!!clean(d.englishRecording)&&!!d.englishListenedBack,
  workout:(+d.workoutMinutes>=20)||(!!d.workoutRecovery&&!!clean(d.recoveryAction)&&+d.recoveryMinutes>=30),
  review:+d.reviewMinutes>=5&&!!clean(d.review1)&&!!clean(d.review2)&&!!clean(d.review3)
 };
}
function evaluateExamRecord(d){const study=+d.examStudyMinutes>=25||+d.examPYQs>=1;const review=!d.examPaperAttempted||( +d.examMistakeMinutes>=10&&!!String(d.examMistakeReview||'').trim());return {exam:!!String(d.examSubject||'').trim()&&study&&review};}
function bindCore(){
$('#executionForm')?.addEventListener('submit',e=>{e.preventDefault();let f=new FormData(e.target),d=personalDay();for(let [k,v] of f.entries())d[k]=v;['phoneFree','commuteSafe','dsaExplained','sprintPushed','workoutRecovery','englishListenedBack','q1Revision','q2Revision','q1Revised','q2Revised'].forEach(k=>d[k]=f.has(k));S.personal.wakeTarget=d.wakeTarget||S.personal.wakeTarget||'';d.done=evaluateDailyRecord(d);d.mode='normal';S.personal.days[today()]=d;save();toast('Daily record saved');render()});
$('#examForm')?.addEventListener('submit',e=>{e.preventDefault();let d=personalDay(),f=new FormData(e.target);Object.assign(d,Object.fromEntries(f));d.examPaperAttempted=f.has('examPaperAttempted');d.done=evaluateExamRecord(d);d.mode='exam';S.personal.days[today()]=d;save();toast('Exam record saved');render()});
$('#milestoneForm')?.addEventListener('submit',e=>{e.preventDefault();let f=new FormData(e.target),m=S.personal.milestones.find(x=>x.id===f.get('id'));if(m){m.proof=f.get('proof');m.completed=f.has('completed');save();render();toast('Milestone updated')}});
$('#weeklyForm')?.addEventListener('submit',e=>{e.preventDefault();const x=Object.fromEntries(new FormData(e.target));x.reviewMinutes=Math.max(0,Math.min(240,+x.reviewMinutes||0));x.date=today();x.weekStart=dateKeysLast7()[0];const isSunday=new Date().getDay()===0;x.completed=weeklyReviewComplete(x,new Date());S.personal.weeklyReviews=Array.isArray(S.personal.weeklyReviews)?S.personal.weeklyReviews:[];const i=S.personal.weeklyReviews.findIndex(v=>v.weekStart===x.weekStart);if(i>=0)S.personal.weeklyReviews[i]=x;else S.personal.weeklyReviews.push(x);S.personal.weeklyReviews=S.personal.weeklyReviews.slice(-104);S.personal.weeklyReview=x;save();toast(x.completed?'Sunday 20-minute weekly review completed':!isSunday?'Draft saved. Weekly review is marked complete on Sunday only.':'Review draft saved; 20 minutes and all reflection fields are needed for completion');render()});
document.querySelectorAll('[data-act]').forEach(b=>b.onclick=()=>act(b.dataset.act));document.querySelectorAll('[data-habit]').forEach(c=>c.onchange=()=>{let a=S.habitLogs[today()]||[],id=c.dataset.habit,habit=S.habits.find(h=>h.id===id);if(c.checked&&habit&&!habitScheduledOn(habit)){c.checked=false;toast('This habit is not scheduled today');return}if(c.checked&&!a.includes(id)){a.push(id);S.habitRewarded=S.habitRewarded||{};S.habitRewarded[today()]=S.habitRewarded[today()]||[];if(!S.habitRewarded[today()].includes(id)){if(S.habitRewarded[today()].length<3){S.habitRewarded[today()].push(id);gain(8,'Habit completed')}else toast('Habit recorded. Daily habit XP limit reached; no activity is lost.')}}else a=a.filter(x=>x!==id);S.habitLogs[today()]=a;save();render()});document.querySelectorAll('[data-task]').forEach(c=>c.onchange=()=>{let t=S.tasks.find(x=>x.id===c.dataset.task);if(t){t.done=c.checked;if(t.done&&!t.rewarded){t.rewarded=true;S.taskRewarded=S.taskRewarded||{};S.taskRewarded[today()]=S.taskRewarded[today()]||[];if(S.taskRewarded[today()].length<3){S.taskRewarded[today()].push(t.id);gain(12,'Planned action completed')}else{save();toast('Action completed and saved. Daily task XP limit reached.')}}else save()}render()});$('#workoutForm')?.addEventListener('submit',e=>{e.preventDefault();let f=new FormData(e.target),rows=[...document.querySelectorAll('.exrow')].map(r=>({name:r.querySelector('[name=exercise]').value,sets:+r.querySelector('[name=sets]').value||1,reps:String(r.querySelector('[name=reps]')?.value||''),weight:+r.querySelector('[name=weight]')?.value||0}));let w={id:uid(),name:f.get('name'),date:f.get('date'),duration:+f.get('duration')||1,effort:f.get('effort'),items:rows,xp:35+rows.length*5};S.workouts.push(w);syncWorkoutToExecution(w.date,w.name);if(canClaimWorkoutXP(w.date)){S.workoutXPClaimed[w.date]=true;gain(w.xp,'Workout: '+w.name)}else{save();if(w.date!==today())toast('Historical workout saved without retroactive XP')}render()});$('#exSearch')?.addEventListener('input',e=>$('#exerciseList').innerHTML=exerciseList(exercises.filter(x=>x.name.toLowerCase().includes(e.target.value.toLowerCase())||x.group.toLowerCase().includes(e.target.value.toLowerCase()))));$('#questForm')?.addEventListener('submit',e=>{e.preventDefault();let f=new FormData(e.target);if(S.quests.length>=20){toast('Keep up to 20 personal quests');return}const name=String(f.get('name')||'').trim();if(!name){toast('Enter a quest name');return}S.quests.push({id:uid(),name:name.slice(0,80),desc:String(f.get('desc')||'').slice(0,240),xp:Math.max(5,Math.min(30,+f.get('xp')||20)),type:'execution'});save();render()});$('#habitForm')?.addEventListener('submit',e=>{e.preventDefault();if(S.habits.length>=10){toast('Keep up to 10 active habits so the list stays manageable');return}const form=new FormData(e.target),name=String(form.get('name')||'').trim(),days=[...new Set(form.getAll('days').map(Number).filter(n=>Number.isInteger(n)&&n>=0&&n<=6))];if(!name){toast('Enter a habit name');return}if(!days.length){toast('Choose at least one scheduled day');return}if(S.habits.some(h=>h.name.toLowerCase()===name.toLowerCase())){toast('That habit already exists');return}S.habits.push({id:uid(),name:name.slice(0,80),target:1,days});save();render()});$('#taskForm')?.addEventListener('submit',e=>{e.preventDefault();let f=new FormData(e.target),date=f.get('date')||today();if(S.tasks.filter(t=>t.date===date).length>=8){toast('Limit this day to eight planned actions; keep the main execution record consolidated');return}const name=String(f.get('name')||'').trim();if(!name){toast('Enter an action');return}S.tasks.push({id:uid(),name:name.slice(0,120),date,priority:f.get('priority'),minutes:Math.max(5,Math.min(240,+f.get('minutes')||25)),done:false});save();render()});$('#recoveryForm')?.addEventListener('submit',e=>{e.preventDefault();let f=new FormData(e.target),r=Object.fromEntries(f);r.date=today();let i=S.recovery.findIndex(x=>x.date===today());if(i>=0)S.recovery[i]=r;else{S.recovery.push(r);gain(5,'Recovery check-in')}save();render()});$('#importFile')?.addEventListener('change',importBackup);$('#units')?.addEventListener('change',e=>{const next=e.target.value,old=S.settings.units;if(next!==old){const factor=next==='lb'?2.2046226218:1/2.2046226218;const cv=v=>v===''||v===null||v===undefined?v:Math.round((+v*factor)*10)/10;if(S.profile.weight)S.profile.weight=cv(S.profile.weight);S.measurements.forEach(m=>{if(m.weight)m.weight=cv(m.weight)});S.workouts.forEach(w=>(w.items||[]).forEach(it=>{if(it.weight)it.weight=cv(it.weight)}));(S.spells||[]).forEach(w=>(w.items||[]).forEach(it=>{if(it.weight)it.weight=cv(it.weight)}));(S.program?.week||[]).forEach(d=>(d.items||[]).forEach(it=>{if(it.weight)it.weight=cv(it.weight)}));(S.activeWorkout?.items||[]).forEach(it=>{if(it.weight)it.weight=cv(it.weight)});}S.settings.units=next;save();render()})}
function actCore(a){if(a==='career'){go('career');return}if(a==='weekly-review'){go('execution');setTimeout(()=>{$('#view').innerHTML=weeklyReview();bind()},0);return}if(a==='toggle-exam'){S.personal.examMode=!S.personal.examMode;save();render();return}if(a==='recovery-day'){let d=personalDay();d.workoutRecovery=true;d.done={...d.done,workout:false};S.personal.days[today()]=d;save();toast('Recovery day selected. Add a 30-minute action, then save today’s record.');render();return}if(a==='new-workout'){go('workout');return}if(a==='execution'||a==='quests'||a==='habits'||a==='workout'){go(a);return}if(a==='add-ex'){let r=document.createElement('div');r.className='formgrid exrow';r.innerHTML=`<select class="field" name="exercise">${exercises.map(e=>`<option>${e.name}</option>`).join('')}</select><input class="field" name="sets" type="number" min="1" value="3"><input class="field" name="reps" type="number" min="1" value="10"><input class="field" name="weight" type="number" min="0" step="0.5" value="0">`;$('#exerciseRows').append(r);return}if(a.startsWith('quest:')){let id=a.split(':')[1];S.questDone[today()]=S.questDone[today()]||[];if(!S.questDone[today()].includes(id)){S.questDone[today()].push(id);let q=S.quests.find(x=>x.id===id);gain(q?.xp||20,'Quest completed: '+(q?.name||''))}render();return}if(a.startsWith('delhabit:')){S.habits=S.habits.filter(x=>x.id!==a.split(':')[1]);save();render();return}if(a.startsWith('deltask:')){S.tasks=S.tasks.filter(x=>x.id!==a.split(':')[1]);save();render();return}if(a==='save-review'){S.reviews=S.reviews||{};S.reviews[today()]=$('#review').value;save();toast('Reflection saved');return}if(a.startsWith('skill:')){let i=+a.split(':')[1];if(!S.skills.includes(i)){S.skills.push(i);let n=skillData[i][0]+' Sigil';if(!S.inventory.includes(n))S.inventory.push(n);gain(15,'Skill unlocked: '+skillData[i][0])}render();return}if(a.startsWith('title:')){S.profile.title=a.slice(6);save();render();return}if(a==='save-spell'){let w=S.workouts.at(-1);if(w){S.spells.push({id:uid(),name:w.name,items:w.items});save();toast('Routine saved')}else toast('Log a workout first');return}if(a.startsWith('spell:')){let s=S.spells.find(x=>x.id===a.split(':')[1]);if(s){go('workout');setTimeout(()=>{let rows=$('#exerciseRows');rows.innerHTML='';s.items.forEach(i=>{let r=document.createElement('div');r.className='formgrid exrow';r.innerHTML=`<select class="field" name="exercise">${exercises.map(e=>`<option ${e.name===i.name?'selected':''}>${e.name}</option>`).join('')}</select><input class="field" name="sets" type="number" min="1" value="${i.sets}"><input class="field" name="reps" type="number" min="1" value="${i.reps||10}"><input class="field" name="weight" type="number" min="0" step="0.5" value="${i.weight||0}">`;rows.append(r)})},0)}return}if(a.startsWith('delspell:')){S.spells=S.spells.filter(x=>x.id!==a.split(':')[1]);save();render();return}if(a==='export'){let blob=new Blob([JSON.stringify(S,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='ascend-backup-'+today()+'.json';link.click();URL.revokeObjectURL(url);toast('Backup exported');return}if(a==='reset'){if(confirm('Delete all Ascend data stored in this browser? Export a backup first if needed.')){localStorage.removeItem('ascend-v1');S=defaultState();S.personal={days:{},examMode:false,milestones:[{id:'m1',name:'150 properly explained DSA questions',target:'150',due:'6 months',proof:''},{id:'m2',name:'Two deployed projects with tests',target:'2',due:'6 months',proof:''},{id:'m3',name:'Five-minute English interview conversation',target:'5 minutes',due:'6 months',proof:''},{id:'m4',name:'Complete Python Backend Internship',target:'Internship completed',due:'1 year',proof:''},{id:'m5',name:'Build a GCP / BigQuery data pipeline',target:'1 project',due:'1 year',proof:''},{id:'m6',name:'Backend or Data Engineering role',target:'Role secured',due:'2 years',proof:''}]};S.program=null;S.activeWorkout=null;S.measurements=[];S.storyProgress=[];S.feedback=[];S.challenges=[];S.challengeClaimed={};S.taskRewarded={};S.restUntil=0;S.learning={completed:[],quizCorrect:{},scores:{},rewarded:{},activity:{}};S.storyReadDate={};S.flashcards=seedFlashcards();S.flashcardsReviewed={};S.flashcardRevealed=false;S.skillPoints=0;S.skillNodes={};S.bossTrials=[];S.schemaVersion=6;S.flashcards=Array.isArray(S.flashcards)?S.flashcards:[];S.flashcardsReviewed=S.flashcardsReviewed&&typeof S.flashcardsReviewed==='object'?S.flashcardsReviewed:{};S.flashcardRevealed=false;S.profile.avatar='aira';S.profile.experience='Beginner';S.profile.equipment='Bodyweight only';S.profile.trainingDays=3;S.profile.sessionDuration=30;S.settings={units:'kg',reminders:false,reminderTime:'20:00',fontScale:'normal',highContrast:false,reduceMotion:false};applyAccessibility();render()}return}}
