function dateKeysLast7(){const end=new Date();end.setHours(12,0,0,0);const start=new Date(end);start.setDate(start.getDate()-((start.getDay()+6)%7));const out=[];for(let d=new Date(start);d<=end;d.setDate(d.getDate()+1))out.push(`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`);return out}
function challengeValue(metric){const keys=dateKeysLast7(),days=keys.map(k=>S.personal.days[k]).filter(Boolean);if(metric==='workouts')return S.workouts.filter(w=>keys.includes(w.date)).length;if(metric==='dsa')return days.filter(d=>d.done?.dsa).length*2;if(metric==='english')return days.reduce((n,d)=>n+(+d.englishMinutes||0),0);if(metric==='build')return days.filter(d=>d.done?.sprint).length;if(metric==='core')return days.reduce((n,d)=>n+(+d.coreMinutes||0),0);return 0}
function challengePeriod(){const d=new Date();d.setHours(0,0,0,0);const day=(d.getDay()+6)%7;d.setDate(d.getDate()-day);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function challenges(){return `<div class="grid">${card(`<div class="eyebrow">SOLO CAMPAIGN</div><h2>Weekly Challenges</h2><p class="muted">A private alternative to online guild competitions. Progress comes from your own activity records; no public ranking, pressure or expired rewards.</p>${S.challenges.map(c=>{const t=challengeTemplates.find(x=>x.id===c.template);if(!t)return '';const v=challengeValue(t.metric),done=v>=t.target,claimed=c.claimedPeriod===challengePeriod()||S.challengeClaimed?.[t.id]===challengePeriod();return `<div class="item"><div class="grow"><b>${esc(t.name)}</b><small>${esc(t.desc)}</small><small>${Math.min(v,t.target)}/${t.target} · ${v} recorded</small>${bar(v,t.target)}</div><span class="badge">+${t.xp} XP</span>${done&&!claimed?btn('Claim','challenge-claim:'+c.id,'primary'):claimed?'<span class="green">Claimed</span>':`<span class="muted">In progress</span>`}${btn('×','challenge-remove:'+c.id,'danger')}</div>`}).join('')||'<p class="muted">Add one challenge to create a gentle weekly target. You can ignore or remove it at any time.</p>'}`,'span8')}${card(`<h3>Choose a challenge</h3>${challengeTemplates.filter(t=>!S.challenges.some(c=>c.template===t.id)).map(t=>`<div class="item"><div class="grow"><b>${esc(t.name)}</b><small>${esc(t.desc)}</small></div>${btn('Add','challenge-add:'+t.id,'ghost')}</div>`).join('')||'<p class="muted">All starter challenges are already on your board.</p>'}<p class="muted">Challenges use the current Monday-starting week and can be claimed once per week. Missing days are not treated as failures.</p>`,'span4')}</div>`}

