const chapterData=[
  {id:'ch1',title:'The First Signal',tag:'Origin',body:'The city called Aster had forgotten how to move. Its people waited for motivation to arrive like a distant storm. One evening, a quiet pulse appeared on the old training terminal: BEGIN WHERE YOU ARE. No prophecy. No chosen one. Only a small action, repeated with care.'},
  {id:'ch2',title:'The Quiet Forge',tag:'Discipline',body:'Beyond the transit gates stood the Quiet Forge, a place where progress was measured in attempts rather than victories. The Forge did not reward exhaustion. It opened when a traveller learned to pause, recover, and return with a clearer plan.'},
  {id:'ch3',title:'The Cartographer’s Trial',tag:'Agency',body:'At the edge of Aster, the Cartographer offered a map with blank spaces. Every route was valid, and every traveller could redraw it. The final test was not to follow the map perfectly; it was to notice what worked and choose the next useful step.'},
  {id:'ch4',title:'The Ember Observatory',tag:'Awareness',body:'At the Observatory, Aira taught the travellers to read signals without obeying every one. Fatigue was information, not a command to quit and not a dare to push harder. The observatory opened when they learned to adjust the route.'},
  {id:'ch5',title:'The Bridge of Returns',tag:'Resilience',body:'The Bridge did not ask who had crossed without pause. It asked who could return after a detour. Kael placed a small marker at the entrance: no debt for yesterday, no punishment for a needed rest, only a next step that fits today.'},
  {id:'ch6',title:'The Aster Constellation',tag:'Mastery',body:'When the six signals aligned, the travellers discovered that mastery was not a final rank. It was a system they could change. The constellation remained visible even when they rested, changed goals or began again.'}
];
function byExercise(name){return exercises.find(e=>e.name===name)||exercises[0]}
function buildProgram(f){
  const goal=f.get('goal')||'General fitness',days=Math.max(2,Math.min(5,+f.get('days')||3)),level=f.get('level')||'Beginner',equipment=f.get('equipment')||'Bodyweight only',duration=Math.max(15,Math.min(90,+f.get('duration')||30));
  let base=planTemplates[goal]||planTemplates['General fitness'];
  if(goal==='Strength'&&equipment==='Bodyweight only')base=planTemplates['General fitness'];
  const week=[];
  for(let i=0;i<days;i++){
    const t=base[i%base.length];
    let list=t.names.map(byExercise).filter(e=>equipment!=='Bodyweight only'||['Bodyweight','None'].includes(e.equipment));
    if(equipment==='Dumbbells + bodyweight')list=list.filter(e=>['Bodyweight','None','Dumbbell'].includes(e.equipment));
    if(!list.length)list=[byExercise('Brisk Walk'),byExercise('Glute Bridge'),byExercise('Bird Dog')];
    const sets=level==='Beginner'?2:3;
    week.push({day:i+1,label:t.label,minutes:duration,restDay:false,items:list.slice(0,5).map(e=>({name:e.name,sets,reps:/Walk|Cycling|Jack|Climber/.test(e.name)?'30 sec':'8–12',weight:0}))});
  }
  return {goal,level,equipment,days,duration,createdAt:today(),week,method:'Rule-based starter template; no AI or medical personalization.'};
}
function programCard(){
  if(!S.program)return `<h3>Build your first weekly program</h3><p class="muted">A transparent rule-based template replaces AI generation. You can change exercises and stop or rest whenever needed.</p><form id="programForm"><div class="formgrid"><label>Primary goal<select class="field" name="goal"><option>General fitness</option><option>Strength</option><option>Muscle building</option><option>Cardio & stamina</option><option>Mobility & movement</option></select></label><label>Experience<select class="field" name="level"><option>Beginner</option><option>Intermediate</option></select></label><label>Available equipment<select class="field" name="equipment"><option>Bodyweight only</option><option>Dumbbells + bodyweight</option><option>Gym access</option></select></label><label>Training days / week<select class="field" name="days"><option>2</option><option selected>3</option><option>4</option><option>5</option></select></label><label>Session duration (min)<select class="field" name="duration"><option>20</option><option selected>30</option><option>45</option><option>60</option></select></label></div><button class="btn primary">Generate starter program</button></form>`;
  const p=S.program;
  return `<div class="row"><div><h3>${esc(p.goal)} · ${p.days} days/week</h3><p class="muted">${esc(p.level)} · ${esc(p.equipment)} · ${p.duration} min target</p></div>${btn('Replace program','clear-program','ghost')}</div><div class="muted small">${esc(p.method)}</div>${p.week.map((d,i)=>`<div class="item"><div class="grow"><b>Day ${d.day} · ${esc(d.label)}</b><small>${d.items.map(x=>esc(x.name)+' ('+x.sets+' × '+esc(x.reps)+')').join(' · ')}</small></div>${btn('Start','program-start:'+i,'primary')}</div>`).join('')}`;
}
function planner(){
 const history=S.workouts.filter(w=>w.date>=new Date(Date.now()-6*86400000).toISOString().slice(0,10));
 const lastRecovery=S.recovery.at(-1);const suggestion=lastRecovery&&(+lastRecovery.energy<=2||+lastRecovery.soreness>=4)?'Your latest check-in reported low energy or high soreness. Consider a lighter session or rest today.':'Use the plan as a flexible guide. A missed session is not debt; continue with the next suitable day.';
 return `<div class="grid">${card(`<div class="eyebrow">TRAINING BLUEPRINT</div>${programCard()}`,'span8')}${card(`<h3>Adaptive guidance (transparent rules)</h3><p>${esc(suggestion)}</p><div class="stat">${history.length}</div><small class="muted">Sessions logged in the last 7 calendar days</small><p class="muted">The planner does not diagnose, estimate your safe maximum, or increase load automatically. Change the plan based on comfort, ability and qualified guidance.</p>`,'span4')}${card(`<h3>Exercise options</h3><p class="muted">Browse a curated starter collection. Select a movement that matches your space and equipment; the workout log remains available without a program.</p>${btn('Open exercise library','workout','primary')}`,'span6')}${card(`<h3>Training week</h3>${S.program?S.program.week.map(d=>`<div class="row"><span>Day ${d.day} · ${esc(d.label)}</span><span class="badge">${d.minutes} min target</span></div>`).join(''):'<p class="muted">Generate a program to see your training week.</p>'}`,'span6')}</div>`;
}
function elapsedSeconds(w){if(!w)return 0;const end=w.paused?w.pausedAt:Date.now();return Math.max(0,Math.floor((end-w.startedAt-(w.pausedMs||0))/1000));}
function clockText(sec){return [Math.floor(sec/3600),Math.floor(sec%3600/60),sec%60].map(x=>String(x).padStart(2,'0')).join(':')}
function stopClock(){if(clockTimer){clearInterval(clockTimer);clockTimer=null}}
function startClock(){stopClock();if(!S.activeWorkout||S.activeWorkout.paused)return;let ticks=0;clockTimer=setInterval(()=>{const el=$('#sessionClock');if(el)el.textContent=clockText(elapsedSeconds(S.activeWorkout));if(S.activeWorkout){S.activeWorkout.lastActiveAt=Date.now();if(++ticks%5===0)save()}const rest=$('#restClock');if(rest&&S.restUntil){const left=Math.max(0,Math.ceil((S.restUntil-Date.now())/1000));rest.textContent=left?clockText(left):'Ready';if(left===0)S.restUntil=0;}},1000)}
function beginWorkout(name,items){S.activeWorkout={id:uid(),name,date:today(),startedAt:Date.now(),lastActiveAt:Date.now(),paused:false,pausedAt:0,pausedMs:0,items:items.map(x=>({...x,weight:x.weight||0,doneSets:[]}))};S.restUntil=0;go('workout')}
function activeWorkoutUI(){const w=S.activeWorkout;if(!w)return '';const completed=w.items.reduce((n,x)=>n+x.doneSets.length,0),planned=w.items.reduce((n,x)=>n+x.sets,0);
 return `<div class="grid">${card(`<div class="eyebrow">ACTIVE SESSION</div><h2>${esc(w.name)}</h2><div class="big cyan" id="sessionClock">${clockText(elapsedSeconds(w))}</div><p class="muted">Elapsed time · timer runs while this tab is open</p><div class="row"><b id="setProgress">${completed}/${planned} sets checked</b><span class="badge">${w.paused?'PAUSED':'IN PROGRESS'}</span></div>${bar(completed,planned)}<div class="actions">${w.paused?btn('Resume','resume-player','primary'):btn('Pause','pause-player','ghost')}${btn('Finish & save','finish-player','primary')}${btn('Cancel session','cancel-player','danger')}</div><div class="item"><div class="grow"><b>Rest timer</b><small id="restClock">${S.restUntil?clockText(Math.max(0,Math.ceil((S.restUntil-Date.now())/1000))):'Not running'}</small></div>${btn('30 sec','rest:30','ghost')}${btn('60 sec','rest:60','ghost')}${btn('90 sec','rest:90','ghost')}</div>`,'span12')}${w.items.map((it,i)=>card(`<h3>${esc(it.name)}</h3><p class="muted">${esc(byExercise(it.name).group)} · ${it.sets} sets · ${esc(it.reps)} target</p><p class="muted">${esc(byExercise(it.name).instructions)}</p><div class="formgrid"><label>Sets<input class="field" type="number" min="1" max="10" data-item-sets="${i}" value="${it.sets}"></label><label>Load (${esc(S.settings.units)})<input class="field" type="number" min="0" step="0.5" data-item-weight="${i}" value="${it.weight||0}"></label></div>${Array.from({length:it.sets},(_,j)=>`<div class="item"><div class="grow">Set ${j+1}</div><input type="checkbox" data-player-set="${i}:${j}" ${it.doneSets.includes(j)?'checked':''} aria-label="Mark ${esc(it.name)} set ${j+1} complete"></div>`).join('')}`,'span6'))}${card(`<h3>Add a movement</h3><div class="formgrid"><select class="field" id="playerAddExercise">${exercises.map(e=>`<option>${esc(e.name)}</option>`).join('')}</select>${btn('Add exercise','add-player-ex','primary')}</div><p class="muted">Use controlled movement and a comfortable range. Stop if you feel pain or concerning symptoms.</p>`,'span12')}</div>`;
}
function workout(){
 if(S.activeWorkout){stopClock();const html=activeWorkoutUI();setTimeout(startClock,0);return html;}
 return `<div class="grid">${card(`<div class="row"><div><h2>Guided workout player</h2><p class="muted">Start a planned routine, tick off each set and save the session history.</p></div><span class="badge">LOCAL TIMER</span></div>${S.program?S.program.week.map((d,i)=>`<div class="item"><div class="grow"><b>${esc(d.label)}</b><small>${d.items.length} exercises · ${d.minutes} min target</small></div>${btn('Start','program-start:'+i,'primary')}</div>`).join(''):btn('Create a program','planner','primary')}<div class="actions">${btn('Quick 20-minute movement session','quick-start','ghost')}</div><p class="muted">Timer runs only while this page is open. For reliability, this app does not promise background timing or notifications.</p>`,'span12')}${card(workoutLegacy(),'span12')}</div>`;
}
function analytics(){
 const total=S.workouts.length,mins=S.workouts.reduce((a,w)=>a+(+w.duration||0),0),sets=S.workouts.reduce((a,w)=>a+w.items.reduce((n,i)=>n+(+i.sets||0),0),0),active=new Set(S.workouts.map(w=>w.date)).size;
 const week=Array.from({length:7},(_,i)=>{let d=new Date();d.setHours(12,0,0,0);d.setDate(d.getDate()-6+i);let key=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;return {label:d.toLocaleDateString(undefined,{weekday:'short'}),n:S.workouts.filter(w=>w.date===key).length}});
 const prs={};S.workouts.forEach(w=>(w.items||[]).forEach(it=>{if(+it.weight>0)prs[it.name]=Math.max(prs[it.name]||0,+it.weight)}));
 const groups={};S.workouts.forEach(w=>(w.items||[]).forEach(it=>{const g=byExercise(it.name).group;groups[g]=(groups[g]||0)+(+it.sets||0)}));
 const latest=S.measurements.at(-1)||{},personal=Object.values(S.personal.days||{});
 const dsa=personal.filter(d=>d.done?.dsa).length*2,build=personal.filter(d=>d.done?.sprint).length;
 const englishDays=personal.filter(d=>d.done?.english).length,englishMins=personal.reduce((n,d)=>n+(+d.englishMinutes||0),0);
 const coreMins=personal.reduce((n,d)=>n+(+d.coreMinutes||0),0),examDays=personal.filter(d=>d.mode==='exam').length,examStudyMins=personal.reduce((n,d)=>n+(+d.examStudyMinutes||0),0),examPYQs=personal.reduce((n,d)=>n+(+d.examPYQs||0),0);
 const recoveryDays=personal.filter(d=>d.done?.workout&&d.workoutRecovery).length,recoveryChecks=S.recovery.length;
 const loggedMisses=personal.reduce((n,d)=>n+Math.max(0,(d.mode==='exam'?1:8)-Object.values(d.done||{}).filter(Boolean).length),0);
 const milestonesDone=(S.personal.milestones||[]).filter(m=>m.completed).length;
 const revisionCount=personal.reduce((n,d)=>n+(d.q1Revision?1:0)+(d.q2Revision?1:0),0);
 return `<div class="grid">${card(`<h2>Progress overview</h2><div class="row"><div><div class="stat">${total}</div><small class="muted">Sessions</small></div><div><div class="stat">${mins}</div><small class="muted">Workout minutes</small></div><div><div class="stat">${sets}</div><small class="muted">Logged sets</small></div><div><div class="stat">${active}</div><small class="muted">Active days</small></div></div>`,'span12')}${card(`<h3>Last 7 days</h3>${week.map(x=>`<div class="row"><span>${x.label}</span><div style="width:72%">${bar(x.n,Math.max(3,...week.map(y=>y.n)))}</div><b>${x.n}</b></div>`).join('')}`,'span6')}${card(`<h3>Training by muscle / movement group</h3>${Object.entries(groups).length?Object.entries(groups).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<div class="row"><span>${esc(k)}</span><b>${v} sets</b></div>`).join(''):'<p class="muted">Log workouts to build your breakdown.</p>'}`,'span6')}${card(`<h3>Load records</h3>${Object.entries(prs).length?Object.entries(prs).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<div class="item"><div class="grow">${esc(k)}</div><b>${v} ${esc(S.settings.units)}</b></div>`).join(''):'<p class="muted">Weighted exercise entries will appear here. These are the highest manually logged loads, not verified strength tests.</p>'}`,'span6')}${card(`<h3>Body measurements (optional)</h3><p class="muted">Stored only in this browser. You can leave these fields blank; body measurements are not a measure of your worth or fitness quality.</p><form id="measurementForm"><div class="formgrid"><label>Date<input class="field" type="date" name="date" value="${today()}"></label><label>Weight (${esc(S.settings.units)})<input class="field" type="number" step=".1" min="0" name="weight" value="${esc(latest.weight||'')}"></label><label>Waist (cm)<input class="field" type="number" step=".1" min="0" name="waist" value="${esc(latest.waist||'')}"></label><label>Notes<input class="field" name="notes" value="" placeholder="Optional context"></label></div><button class="btn primary">Save measurement</button></form>${S.measurements.slice().reverse().slice(0,6).map(m=>`<div class="item"><div class="grow"><b>${esc(m.date)}</b><small>${m.weight?`Weight ${esc(m.weight)} ${esc(S.settings.units)} · `:''}${m.waist?`Waist ${esc(m.waist)} cm`:''}</small></div></div>`).join('')}`,'span6')}${card(`<h3>Personal execution analytics</h3><p class="muted">Based on the one daily record. These are self-entered results, not independently verified.</p><div class="row"><div><div class="stat">${dsa}</div><small class="muted">DSA questions explained</small></div><div><div class="stat">${build}</div><small class="muted">Build days pushed</small></div><div><div class="stat">${englishMins}</div><small class="muted">English minutes</small></div><div><div class="stat">${coreMins}</div><small class="muted">Core CS minutes</small></div></div><div class="row"><div><div class="stat">${examDays}</div><small class="muted">Exam days</small></div><div><div class="stat">${examPYQs}</div><small class="muted">Exam PYQs</small></div><div><div class="stat">${recoveryDays}</div><small class="muted">Logged recovery days</small></div><div><div class="stat">${milestonesDone}</div><small class="muted">Career milestones complete</small></div></div><div class="row"><span>English recording sessions</span><b>${englishDays}</b></div><div class="row"><span>Separate recovery check-ins</span><b>${recoveryChecks}</b></div><div class="row"><span>Problems marked for revision</span><b>${revisionCount}</b></div><div class="row"><span>Tasks not marked done in saved records</span><b>${loggedMisses}</b></div><p class="muted">Days without a saved daily record are excluded. The unfinished-task number is descriptive only; it creates no backlog or penalty.</p>`,'span12')}${card(`<h3>Offline learning deck</h3><div class="row"><span>Flashcards</span><b>${S.flashcards.length}</b></div><div class="row"><span>Reviewed today</span><b>${Object.values(S.flashcardsReviewed||{}).filter(v=>v===today()).length}</b></div><div class="row"><span>Due cards</span><b>${S.flashcards.filter(c=>(c.due||today())<=today()).length}</b></div>${btn('Open flashcards','flashcards','ghost')}`,'span6')}</div>`;
}
function story(){return `<div class="grid">${card(`<div class="eyebrow">THE WORLD OF ASTER</div><h2>Ascend: The First Signal</h2><p class="muted">An original setting about agency, sustainable effort and learning to return—not a retelling of another franchise.</p>${chapterData.map((c,i)=>`<div class="item"><div class="grow"><span class="badge">${esc(c.tag)}</span><h3>${esc(c.title)}</h3><p>${esc(c.body)}</p></div>${S.storyProgress.includes(c.id)?'<span class="green">Read</span>':btn('Read chapter','chapter:'+i,'primary')}</div>`).join('')}`,'span8')}${card(`<h3>Field notes</h3><p class="muted">The story grows as the product grows. This text-first chapter system is the offline alternative to commissioned character art, animation and voice acting.</p><p>Progression is a celebration, not a test of personal worth.</p>`,'span4')}</div>`;}
function help(){return `<div class="grid">${card(`<h2>Help & practical alternatives</h2><details open><summary>Where is cloud sync?</summary><p class="muted">This release stores everything in this browser. Use Settings → Export JSON to move your data manually. Account login and cloud sync require a secure backend, which is not bundled here.</p></details><details><summary>Why are there no automatic background reminders?</summary><p class="muted">The app can show an opt-in reminder while it is open. Closed-app reminders vary by browser and operating system. Use your device’s built-in alarm/calendar for a dependable local reminder; ASCEND does not contact a push service.</p></details><details><summary>Can it record my spoken English?</summary><p class="muted">No microphone recording is stored by this build. Record with your phone’s voice recorder and paste the file name or a private file reference into the execution tracker.</p></details><details><summary>Are workout plans AI-generated?</summary><p class="muted">No. Program templates are transparent rules, not AI or medical recommendations. Review exercises and adapt them to your ability, equipment and professional advice.</p></details><details><summary>How do I share a progress report?</summary><p class="muted">Export your JSON backup from Settings. It contains personal records; inspect it and remove private information before sharing publicly.</p></details>`,'span7')}${card(`<h3>Local feedback note</h3><p class="muted">Save a bug report or suggestion in this browser. It will be included in the JSON backup so you can copy it into your GitHub issue tracker.</p><form id="feedbackForm"><label>Type<select class="field" name="type"><option>Bug report</option><option>Feature suggestion</option><option>Usability feedback</option></select></label><label>Message<textarea class="field" name="message" rows="5" required></textarea></label><button class="btn primary">Save feedback locally</button></form>${S.feedback.slice(-3).reverse().map(f=>`<div class="item"><div class="grow"><b>${esc(f.type)}</b><small>${esc(f.date)} · ${esc(f.message)}</small></div></div>`).join('')}`,'span5')}</div>`;}
function settings(){return `<div class="grid">${card(`<h2>Settings & data</h2><p class="muted">Offline-first: your records stay in this browser. Export before clearing browser data or changing devices.</p><div class="actions">${btn('Export JSON backup','export','primary')}${btn('Export encrypted backup','export-encrypted','ghost')}<label class="btn">Import backup<input type="file" id="importFile" accept=".json,.ascendbackup,application/json,application/octet-stream" hidden></label>${btn('Reset local data','reset','danger')}${btn('Install app','install-app','ghost')}</div><label>Weight units<select class="field" id="units"><option ${S.settings.units==='kg'?'selected':''}>kg</option><option ${S.settings.units==='lb'?'selected':''}>lb</option></select></label><h3>Reminder (while app is open)</h3><label><input id="reminders" type="checkbox" ${S.settings.reminders?'checked':''}> Enable an in-app daily reminder</label><label>Reminder time<input class="field" type="time" id="reminderTime" value="${esc(S.settings.reminderTime)}"></label><p class="muted">Background delivery while the app is closed is not guaranteed. Browser notification permission is optional.</p><div class="actions">${btn('Request notification permission','notification-permission','ghost')}${btn('Send test notification','test-notification','ghost')}</div><h3>Accessibility</h3><label>Text size<select class="field" id="fontScale"><option value="normal" ${S.settings.fontScale==='normal'?'selected':''}>Normal</option><option value="large" ${S.settings.fontScale==='large'?'selected':''}>Large</option></select></label><label><input type="checkbox" id="highContrast" ${S.settings.highContrast?'checked':''}> Higher contrast</label><label><input type="checkbox" id="reduceMotion" ${S.settings.reduceMotion?'checked':''}> Reduce motion</label>`,'span7')}${card(`<h3>Privacy & product boundaries</h3><div class="big cyan">ASCEND</div><p class="muted">Version 1.4 · expanded offline-first build</p><p class="muted">No account, remote analytics, AI Coach, subscription, ad tracking or social leaderboard is included. This avoids collecting data or inventing online features without infrastructure.</p><p class="muted">ASCEND is intentionally offline-only. There will be no backend, cloud sync, account, online social system or remote API. Use private solo progression and portable backups.</p>`,'span5')}</div>`;}
function bindEnhancements(){
 $('#onboardingForm')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);S.profile.name=String(f.get('name')||'Hunter').trim()||'Hunter';S.profile.goal=f.get('goal')||'Build consistency';S.profile.experience=f.get('level')||'Beginner';S.profile.equipment=f.get('equipment')||'Bodyweight only';S.workoutXPClaimed=S.workoutXPClaimed&&typeof S.workoutXPClaimed==='object'?S.workoutXPClaimed:{};S.challengeClaimed=S.challengeClaimed&&typeof S.challengeClaimed==='object'?S.challengeClaimed:{};S.taskRewarded=S.taskRewarded&&typeof S.taskRewarded==='object'?S.taskRewarded:{};S.profile.avatar=S.profile.avatar||'aira';S.profile.trainingDays=+f.get('days')||3;S.profile.sessionDuration=+f.get('duration')||30;S.profile.onboarded=true;if(f.has('createProgram'))S.program=buildProgram(f);save();toast('Character setup saved');render()});
 const filterExercises=()=>{const q=($('#exSearch')?.value||'').toLowerCase(),g=$('#exGroupFilter')?.value||'',eq=$('#exEquipmentFilter')?.value||'';const hits=exercises.filter(x=>(!q||[x.name,x.group,x.equipment,x.level].some(v=>v.toLowerCase().includes(q)))&&(!g||x.group===g)&&(!eq||x.equipment===eq));const list=$('#exerciseList');if(list)list.innerHTML=exerciseList(hits)};
 $('#exSearch')?.addEventListener('input',filterExercises);$('#exGroupFilter')?.addEventListener('change',filterExercises);$('#exEquipmentFilter')?.addEventListener('change',filterExercises);
 $('#programForm')?.addEventListener('submit',e=>{e.preventDefault();S.program=buildProgram(new FormData(e.target));save();toast('Starter program created');go('planner')});
 
 $('#feedbackForm')?.addEventListener('submit',e=>{e.preventDefault();let x=Object.fromEntries(new FormData(e.target));S.feedback.push({...x,date:today()});save();toast('Feedback saved in this browser');render()});
 document.querySelectorAll('[data-player-set]').forEach(c=>c.onchange=()=>{const [i,j]=c.dataset.playerSet.split(':').map(Number),w=S.activeWorkout,it=w?.items[i];if(!it)return;it.doneSets=it.doneSets||[];it.doneSets=c.checked?[...new Set([...it.doneSets,j])]:it.doneSets.filter(n=>n!==j);save();const count=w.items.reduce((n,x)=>n+x.doneSets.length,0),total=w.items.reduce((n,x)=>n+x.sets,0);const el=$('#setProgress');if(el)el.textContent=count+'/'+total+' sets checked';const b=$('#view .bar i');if(b)b.style.width=(total?count/total*100:0)+'%' });
 document.querySelectorAll('[data-item-sets]').forEach(el=>el.onchange=()=>{const i=+el.dataset.itemSets,it=S.activeWorkout?.items[i];if(!it)return;it.sets=Math.max(1,Math.min(10,+el.value||1));it.doneSets=(it.doneSets||[]).filter(n=>n<it.sets);save();render()});
 document.querySelectorAll('[data-item-weight]').forEach(el=>el.onchange=()=>{const i=+el.dataset.itemWeight,it=S.activeWorkout?.items[i];if(it){it.weight=Math.max(0,+el.value||0);save()}});
 $('#reminders')?.addEventListener('change',e=>{S.settings.reminders=e.target.checked;save();if(S.settings.reminders&&!reminderTimer)reminderTimer=setInterval(checkReminder,30000);if(!S.settings.reminders&&reminderTimer){clearInterval(reminderTimer);reminderTimer=null}});
 $('#reminderTime')?.addEventListener('change',e=>{S.settings.reminderTime=e.target.value;save()});
 $('#fontScale')?.addEventListener('change',e=>{S.settings.fontScale=e.target.value;save();applyAccessibility()});
 $('#highContrast')?.addEventListener('change',e=>{S.settings.highContrast=e.target.checked;save();applyAccessibility()});
 $('#reduceMotion')?.addEventListener('change',e=>{S.settings.reduceMotion=e.target.checked;save();applyAccessibility()});
}
function applyAccessibility(){document.body.classList.toggle('large-text',S.settings.fontScale==='large');document.body.classList.toggle('high-contrast',!!S.settings.highContrast);document.body.classList.toggle('reduce-motion',!!S.settings.reduceMotion)}
function checkReminder(force=false){if(!S.settings.reminders||!S.settings.reminderTime)return;if(document.hidden&&(!('Notification'in window)||Notification.permission!=='granted'))return;const now=new Date(),hhmm=now.toTimeString().slice(0,5),key=today()+'@'+S.settings.reminderTime;if(hhmm<S.settings.reminderTime||S.reminderShown===key)return;S.reminderShown=key;save();if('Notification'in window&&Notification.permission==='granted'){try{new Notification('ASCEND · Daily reset',{body:'Take a moment to choose one useful next step.'})}catch{toast('Daily reminder: choose one useful next step.')}}else toast('Daily reminder: choose one useful next step.');}
function act(a){
 if(a==='skip-onboarding'){S.profile.onboarded=true;save();render();return}
 if(a.startsWith('challenge-add:')){const id=a.split(':')[1];if(S.challenges.length>=3){toast('Keep up to three active weekly challenges');return}if(!S.challenges.some(c=>c.template===id)&&challengeTemplates.some(c=>c.id===id))S.challenges.push({id:uid(),template:id});save();render();return}
 if(a.startsWith('challenge-claim:')){const id=a.split(':')[1],c=S.challenges.find(x=>x.id===id),t=challengeTemplates.find(x=>x.id===c?.template);if(!c||!t)return;S.challengeClaimed=S.challengeClaimed||{};const period=challengePeriod();if(S.challengeClaimed[t.id]===period){toast('This weekly challenge reward has already been claimed');return}const v=challengeValue(t.metric);if(v<t.target||c.claimedPeriod===period){toast('Challenge is not ready to claim');return}c.claimedPeriod=period;S.challengeClaimed[t.id]=period;const reward='Weekly Sigil · '+t.name;if(!S.inventory.includes(reward))S.inventory.push(reward);gain(t.xp,'Challenge completed: '+t.name);render();return}
 if(a.startsWith('challenge-remove:')){S.challenges=S.challenges.filter(c=>c.id!==a.split(':')[1]);save();render();return}
 if(a.startsWith('quest:')){const id=a.split(':')[1],q=S.quests.find(x=>x.id===id);if(q&&!questEligible(q)){toast('Complete the linked activity before claiming this quest');return}}
 if(['planner','challenges','story','academy','help','analytics','settings','recovery','skills','achievements','inventory','spellbook','profile'].includes(a)){go(a);return}
 if(a==='install-app'){if(deferredInstallPrompt){deferredInstallPrompt.prompt();deferredInstallPrompt.userChoice.then(()=>{deferredInstallPrompt=null})}else toast('Use your browser menu → Install app / Add to Home Screen');return}
 if(a==='notification-permission'){if(!('Notification'in window)){toast('Browser notifications are not supported here');return}Notification.requestPermission().then(x=>toast(x==='granted'?'Notifications enabled':'Permission not granted'));return}
 if(a==='test-notification'){if('Notification'in window&&Notification.permission==='granted'){try{new Notification('ASCEND notification test',{body:'Notifications are working while the browser allows them.'})}catch{toast('The browser blocked the notification.')}}else toast('Enable permission first; an in-app reminder remains available.');return}
 if(a==='clear-program'){if(confirm('Replace the current program?')){S.program=null;save();render()}return}
 if(a.startsWith('program-start:')){const i=+a.split(':')[1],d=S.program?.week[i];if(d)beginWorkout(d.label,d.items);return}
 if(a==='quick-start'){beginWorkout('Quick movement session',[{name:'Brisk Walk',sets:1,reps:'5 min',weight:0},{name:'Squat',sets:2,reps:'8–12',weight:0},{name:'Incline Push-up',sets:2,reps:'8–12',weight:0},{name:'Bird Dog',sets:2,reps:'8 each side',weight:0}]);return}
 if(a==='pause-player'){let w=S.activeWorkout;if(w&&!w.paused){w.paused=true;w.pausedAt=Date.now();stopClock();save();render()}return}
 if(a==='resume-player'){let w=S.activeWorkout;if(w?.paused){w.pausedMs=(w.pausedMs||0)+(Date.now()-w.pausedAt);w.paused=false;w.pausedAt=0;w.lastActiveAt=Date.now();save();render()}return}
 if(a.startsWith('rest:')){S.restUntil=Date.now()+Number(a.split(':')[1])*1000;save();toast('Rest timer started');return}
 if(a==='add-player-ex'){const name=$('#playerAddExercise')?.value||'Squat';S.activeWorkout.items.push({name,sets:3,reps:'8–12',weight:0,doneSets:[]});save();render();return}
 if(a==='cancel-player'){if(confirm('Discard this active session?')){S.activeWorkout=null;S.restUntil=0;stopClock();render()}return}
 if(a==='finish-player'){const w=S.activeWorkout;if(!w)return;const completed=w.items.reduce((n,x)=>n+x.doneSets.length,0);if(!completed&&!confirm('No sets are checked off. Save this session anyway?'))return;const minutes=Math.max(1,Math.round(elapsedSeconds(w)/60)),items=w.items.map(x=>({...x,sets:x.doneSets.length||0,plannedSets:x.sets})).filter(x=>x.sets>0);const record={id:w.id,name:w.name,date:w.date,duration:minutes,effort:'Self-rated',items,xp:completed?35+completed*4:0};S.workouts.push(record);syncWorkoutToExecution(record.date,record.name);S.activeWorkout=null;S.restUntil=0;stopClock();if(record.xp&&canClaimWorkoutXP(record.date)){S.workoutXPClaimed[record.date]=true;gain(record.xp,'Workout completed: '+record.name)}else{save();toast(record.xp?'Session saved; today’s workout XP was already claimed.':'Session saved without set XP because no sets were checked.')}go('workout');return}
 if(a.startsWith('chapter:')){const c=chapterData[+a.split(':')[1]];if(c&&!S.storyProgress.includes(c.id)){S.storyProgress.push(c.id);S.inventory.push('Aster Chapter Sigil · '+c.tag);gain(10,'Story chapter read: '+c.title)}if(c){S.storyReadDate=S.storyReadDate||{};S.storyReadDate[today()]=true;save()}render();return}
 return actCore(a);
}

function bind(){bindCore();bindEnhancements()}
document.addEventListener('visibilitychange',()=>{if(document.hidden&&S.activeWorkout&&!S.activeWorkout.paused){S.activeWorkout.paused=true;S.activeWorkout.pausedAt=Date.now();stopClock();save()}});
window.addEventListener('pagehide',()=>{if(S.activeWorkout&&!S.activeWorkout.paused){S.activeWorkout.paused=true;S.activeWorkout.pausedAt=Date.now();stopClock();save()}});


// ========================== ASCEND 1.4 ===============================
