 const filterExercises=()=>{const q=($('#exSearch')?.value||'').toLowerCase(),g=$('#exGroupFilter')?.value||'',eq=$('#exEquipmentFilter')?.value||'',lv=$('#exLevelFilter')?.value||'';const hits=exercises.filter(x=>(!q||[x.name,x.group,x.equipment,x.level,x.instructions,x.easier].some(v=>String(v).toLowerCase().includes(q)))&&(!g||x.group===g)&&(!eq||x.equipment===eq)&&(!lv||x.level===lv));const el=$('#exerciseList');if(el)el.innerHTML=exerciseList(hits)};
 $('#exSearch')?.addEventListener('input',filterExercises);$('#exGroupFilter')?.addEventListener('change',filterExercises);$('#exEquipmentFilter')?.addEventListener('change',filterExercises);$('#exLevelFilter')?.addEventListener('change',filterExercises);
 $('#importFile')?.removeEventListener('change',importBackup);$('#importFile')?.addEventListener('change',importBackupV14);
