 $('#planEditForm')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target),i=S.editProgramDay,d=S.program?.week?.[i];if(!d)return;d.label=String(f.get('label')||d.label).trim();d.items=d.items.map((it,j)=>({name:String(f.get('itemName'+j)||it.name),sets:Math.max(1,Math.min(10,+f.get('itemSets'+j)||1)),reps:String(f.get('itemReps'+j)||it.reps),weight:it.weight||0}));const addName=String(f.get('newExercise')||'');if(addName&&d.items.length<8)d.items.push({name:addName,sets:Math.max(1,Math.min(10,+f.get('newSets')||2)),reps:String(f.get('newReps')||'8–12'),weight:0});S.editProgramDay=null;save();toast('Training day updated');render()});
 document.querySelectorAll('[data-plan-remove]').forEach(b=>b.addEventListener('click',()=>{const [i,j]=b.dataset.planRemove.split(':').map(Number),d=S.program?.week?.[i];if(d&&d.items.length>1){d.items.splice(j,1);save();render()}else toast('Keep at least one movement in a training day')}));
