 $('#measurementForm')?.addEventListener('submit',e=>{e.preventDefault();const x=Object.fromEntries(new FormData(e.target));if(!x.weight&&!x.waist){toast('Enter a weight or waist value');return}S.measurements.push({...x,id:uid()});if(x.weight)S.profile.weight=x.weight;save();toast('Measurement saved');render()});
